    },
    {
      "card_ids": ["C07"],
      "claim": "Poor PET brain uptake of cationic muscarinic ligands such as QNB reflects basic amine/ester and transporter liabilities absent in carbamazepine.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C09"],
      "claim": "U0126's 5% cortex/plasma ratio is associated with a polar, nitrile-rich MEK-inhibitor scaffold; carbamazepine is a lipophilic neutral tricyclic, so this negative evidence is mechanistically non-transferable.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
